    @Override
    public Entrega calcular(Pedido pedido) {
        BigDecimal frete = FIXO.add(POR_KG.multiply(pedido.pesoTotalKg()));
        return new Entrega(Dinheiro.emCentavos(frete), PRAZO_DIAS);
    }
}
